/**
 * Voter registration rules and deadlines for the Nov 3, 2026 general
 * election — GENERATED by scripts/build-voter-registration-2026.ts from
 * the frozen vote.gov states.json (registration links, Aug 2024) plus
 * hand verification of every deadline against official state sources on
 * the verification date below. Do not edit rows by hand; re-run the
 * verification pass and regenerate.
 *
 * Coverage: 50 states + DC. Territories are excluded (no maintained
 * official machine source; their delegates' race pages stand alone).
 * A null deadline means "not verified from an official source" — the UI
 * must degrade to "check your state's site", never guess.
 */

export interface StateVoterRegistration2026 {
  state: string;
  stateName: string;
  /** North Dakota has no voter registration at all. */
  registrationRequired: boolean;
  sameDayRegistration: boolean;
  /**
   * Where same-day registration actually applies. 'through-election-day'
   * includes registering at the polls or a voter service center on
   * Election Day; 'early-voting-only' means it ends before Election Day
   * (e.g. North Carolina). null when there is no same-day registration.
   */
  sameDayScope: 'through-election-day' | 'early-voting-only' | null;
  sameDayNotes: string | null;
  onlineRegistrationAvailable: boolean;
  /**
   * True only where the state itself says online registration has no
   * cutoff (Hawaii). A null onlineDeadline WITHOUT this flag means the
   * deadline exists but is unverified — render nothing, never "any time".
   */
  onlineNoDeadline: boolean;
  /** ISO dates for the Nov 3, 2026 general election. */
  onlineDeadline: string | null;
  mailDeadline: string | null;
  mailDeadlineType: 'postmarked' | 'received' | null;
  inPersonDeadline: string | null;
  /** The rule in the state's own words (e.g. "15 days before Election Day"). */
  rule: string;
  registrationUrl: string | null;
  checkRegistrationUrl: string | null;
  infoUrl: string | null;
  electionOfficeUrl: string | null;
  /** Official page stating the deadline rule. */
  deadlineSource: string | null;
  sourceKind: 'state-official' | 'federal-official' | 'unverified';
  verifiedAt: string | null;
  notes: string | null;
}

